/**
 * The report's language for the parts every PDF shares: the footer (the
 * disclaimer, which reuses the app footer's approved wording, and the
 * "generated by" line), the cover's date line and notice, and the
 * empty-table line. A report is rendered inside `withPdfLocale(locale, ...)`;
 * the shared primitives read the language from there, so no page has to pass
 * it along. Outside it they keep English.
 *
 * Export routes run as React Server Components code, where React context is
 * not available; the language is carried with AsyncLocalStorage instead,
 * which follows the render of one request and never leaks into another.
 */
import { AsyncLocalStorage } from "node:async_hooks";
import en from "@/messages/en.json";
import es from "@/messages/es.json";

export type PdfLocale = "en" | "es";

const store = new AsyncLocalStorage<PdfLocale>();

export function toPdfLocale(locale: string | null | undefined): PdfLocale {
  return locale?.toLowerCase().startsWith("es") ? "es" : "en";
}

/** Run `render` (a renderToBuffer call) with the shared PDF wording in `locale`. */
export function withPdfLocale<T>(locale: string | null | undefined, render: () => T): T {
  return store.run(toPdfLocale(locale), render);
}

export interface PdfChrome {
  disclaimer: string;
  generatedBy: string;
  noRecords: string;
  /** "Generated {date}" on a cover. */
  generated: (date: string) => string;
  confidentialBody: string;
}

function chrome(m: typeof en): PdfChrome {
  return {
    disclaimer: m.footer.disclaimer,
    generatedBy: m.pdf.chrome.generatedBy,
    noRecords: m.pdf.chrome.noRecords,
    generated: (date) => m.pdf.common.generated.replace("{date}", date),
    confidentialBody: m.pdf.common.confidentialBody,
  };
}

export const PDF_CHROME: Record<PdfLocale, PdfChrome> = { en: chrome(en), es: chrome(es as typeof en) };

/** The shared wording in the language of the report being rendered. */
export function pdfChrome(): PdfChrome {
  return PDF_CHROME[store.getStore() ?? "en"];
}
